public static void check(Solution solution) {
    assert Arrays.equals(solution.queryResults(3, new int[]{{0,1},{1,2},{2,3},{0,1}}), new int[]{1, 2, 3, 3});
    assert Arrays.equals(solution.queryResults(1, new int[]{{0,1},{1,2}}), new int[]{1, 2});
